const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("chillerState") || {
    kind: "ChillerState",
    version: 1,
    // Chiller_1 (0x18008040x)
    tmsOperatingMode: null,
    outletCoolantTempC: null,
    inletCoolantTempC: null,
    ambientTempC: null,
    inletCoolantPressure: null,
    outletCoolantPressure: null,
    heartbeat: null,
    tmsFaultCode: null,
    tmsFaultLevel: null,
    // Chiller_2_Status (0x18018040x)
    compressorStatus: null,
    crankcaseHeaterStatus: null,
    electricHeaterStatus: null,
    pumpStatus: null,
    fanRunStatus: null,
    compressorSpeed: null,
    pumpSpeed: null,
    onOffStatus: null
};

// Helper functions
function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function s8(buf, offset) {
    let val = buf[offset] & 0xFF;
    return val > 127 ? val - 256 : val;
}

function getBit(buf, byteOffset, bitOffset) {
    return ((buf[byteOffset] >> bitOffset) & 0x01) === 1;
}

function getBits(buf, byteOffset, bitOffset, length) {
    return (buf[byteOffset] >> bitOffset) & ((1 << length) - 1);
}

var processed = false;

// ==================== Chiller_1 (0x18008040x) ====================
// CAN ID pattern: 0x180080400 - 0x18008040F
if ((canId & 0xFFFFFFF0) === 0x18008040) {
    processed = true;
    // Bit 0-2: TMS Operating Mode (3 bit)
    state.tmsOperatingMode = getBits(data, 0, 0, 3);
    // Bit 8-15: Outlet Coolant Temp (8 bit, Factor: 1, Offset: -40)
    state.outletCoolantTempC = u8(data, 1) - 40;
    // Bit 16-23: Inlet Coolant Temp (8 bit, Factor: 1, Offset: -40)
    state.inletCoolantTempC = u8(data, 2) - 40;
    // Bit 24-31: Ambient Temp (8 bit, Factor: 1, Offset: -40)
    state.ambientTempC = u8(data, 3) - 40;
    // Bit 32-39: Inlet Coolant Pressure (8 bit, Factor: 0.1, Signed)
    state.inletCoolantPressure = s8(data, 4) * 0.1;
    // Bit 40-47: Outlet Coolant Pressure (8 bit, Factor: 0.1, Signed)
    state.outletCoolantPressure = s8(data, 5) * 0.1;
    // Bit 48-55: Heartbeat (8 bit)
    state.heartbeat = u8(data, 6);
    // Bit 56-61: TMS Fault Code (6 bit)
    state.tmsFaultCode = getBits(data, 7, 0, 6);
    // Bit 62-63: TMS Fault Level (2 bit)
    state.tmsFaultLevel = getBits(data, 7, 6, 2);
}

// ==================== Chiller_2_Status (0x18018040x) ====================
// CAN ID pattern: 0x180180400 - 0x18018040F
if ((canId & 0xFFFFFFF0) === 0x18018040) {
    processed = true;
    // Bit 0: Compressor Status
    state.compressorStatus = getBit(data, 0, 0);
    // Bit 1: Crankcase Heater Status
    state.crankcaseHeaterStatus = getBit(data, 0, 1);
    // Bit 2: Electric Heater Status
    state.electricHeaterStatus = getBit(data, 0, 2);
    // Bit 3: Pump Status
    state.pumpStatus = getBit(data, 0, 3);
    // Bit 4: Fan Run Status
    state.fanRunStatus = getBit(data, 0, 4);
    // Bit 8-15: Compressor Speed (8 bit, Factor: 100)
    state.compressorSpeed = u8(data, 1) * 100;
    // Bit 16-23: Pump Speed (8 bit, Factor: 100)
    state.pumpSpeed = u8(data, 2) * 100;
    // Bit 24-31: ON/OFF Status (8 bit)
    state.onOffStatus = u8(data, 3);
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("chillerState", state);
msg.payload = state;
return msg;

var state = flow.get("chillerState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;

const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

// Only process BCU_01_Fault_Message (0x18FF16F0)
if (canId !== 0x18FF16F0) {
    return null;
}

// Helper function to get bit value
function getBit(buf, bitIndex) {
    const byteIndex = Math.floor(bitIndex / 8);
    const bitOffset = bitIndex % 8;
    return ((buf[byteIndex] >> bitOffset) & 0x01) === 1;
}

let state = {
    kind: "ContainerBatteryFaultState",
    version: 1,
    timestampUtc: new Date().toISOString(),

    // ==================== Byte 0 (Bit 0-7) ====================
    faultPackWarning: getBit(data, 0),
    faultPackDanger: getBit(data, 1),
    faultCellOverVoltageWarning: getBit(data, 2),
    faultCellOverVoltageDanger: getBit(data, 3),
    faultCellUnderVoltageWarning: getBit(data, 4),
    faultCellUnderVoltageDanger: getBit(data, 5),
    faultCellOverTempWarning: getBit(data, 6),
    faultCellOverTempDanger: getBit(data, 7),

    // ==================== Byte 1 (Bit 8-15) ====================
    faultCellUnderTempWarning: getBit(data, 8),
    faultCellUnderTempDanger: getBit(data, 9),
    warningPackOC: getBit(data, 10),
    faultPackOC: getBit(data, 11),
    faultPackCurrentSensor: getBit(data, 12),
    faultPackDischargeContactor: getBit(data, 13),
    faultPackChargeContactor: getBit(data, 14),
    faultFuse: getBit(data, 15),

    // ==================== Byte 2 (Bit 16-23) ====================
    faultPackHVIL2: getBit(data, 16),
    faultPackFuse: getBit(data, 17),
    faultPackFireWarningSensor: getBit(data, 18),
    faultPackHighHumidity: getBit(data, 19),
    faultPackBMU: getBit(data, 20),
    faultPackNegContactor: getBit(data, 21),
    faultPackPrecharge: getBit(data, 22),
    faultIsolation: getBit(data, 23),

    // ==================== Byte 3 (Bit 24-31) ====================
    faultPackEmergency: getBit(data, 24),
    warningModuleTempBalance: getBit(data, 25),
    faultModuleTempBalance: getBit(data, 26),

    // ==================== Byte 4 (Bit 32-39) ====================
    faultDeadCell: getBit(data, 32),
    faultCANCommunication: getBit(data, 33),
    faultPackIntCommunication: getBit(data, 34),
    faultInternalMeasurement: getBit(data, 35),
    faultVoltageRedundancy: getBit(data, 36),
    faultOpenWire: getBit(data, 37),

    // ==================== Byte 5 (Bit 40-47) ====================
    faultBoardBMUNoResponse: getBit(data, 40),
    faultBoardStackInitialize: getBit(data, 41),
    faultBoardMeasurement: getBit(data, 42),
    faultBoardStackConfiguration: getBit(data, 43),
    faultBoardBalance: getBit(data, 44),
    faultBoardOperationSystem: getBit(data, 45),

    // ==================== Byte 6 (Bit 48-55) ====================
    faultBoardGPI: getBit(data, 48),
    faultBoardChip: getBit(data, 49),
    faultBoardSys: getBit(data, 50),
    faultBoardCommunication: getBit(data, 51),
    faultBoardCompOverVoltage: getBit(data, 52),
    faultBoardCompUnderVoltage: getBit(data, 53),
    faultBoardAuxOverVoltage: getBit(data, 54),
    faultBoardAuxUnderVoltage: getBit(data, 55),

    // ==================== Byte 7 (Bit 56-63) ====================
    faultBoardOverVoltage: getBit(data, 56),
    faultBoardUnderVoltage: getBit(data, 57),
    faultBoardStackError: getBit(data, 58),
    faultBoardOpenWireDetect: getBit(data, 59)
};

// ==================== Derived Fields ====================

// Warning flags list
const warningFlags = [
    'faultPackWarning',
    'faultCellOverVoltageWarning',
    'faultCellUnderVoltageWarning',
    'faultCellOverTempWarning',
    'faultCellUnderTempWarning',
    'warningPackOC',
    'warningModuleTempBalance'
];

// All fault flags (excluding warnings)
const faultFlags = [
    'faultPackDanger',
    'faultCellOverVoltageDanger',
    'faultCellUnderVoltageDanger',
    'faultCellOverTempDanger',
    'faultCellUnderTempDanger',
    'faultPackOC',
    'faultPackCurrentSensor',
    'faultPackDischargeContactor',
    'faultPackChargeContactor',
    'faultFuse',
    'faultPackHVIL2',
    'faultPackFuse',
    'faultPackFireWarningSensor',
    'faultPackHighHumidity',
    'faultPackBMU',
    'faultPackNegContactor',
    'faultPackPrecharge',
    'faultIsolation',
    'faultPackEmergency',
    'faultModuleTempBalance',
    'faultDeadCell',
    'faultCANCommunication',
    'faultPackIntCommunication',
    'faultInternalMeasurement',
    'faultVoltageRedundancy',
    'faultOpenWire',
    'faultBoardBMUNoResponse',
    'faultBoardStackInitialize',
    'faultBoardMeasurement',
    'faultBoardStackConfiguration',
    'faultBoardBalance',
    'faultBoardOperationSystem',
    'faultBoardGPI',
    'faultBoardChip',
    'faultBoardSys',
    'faultBoardCommunication',
    'faultBoardCompOverVoltage',
    'faultBoardCompUnderVoltage',
    'faultBoardAuxOverVoltage',
    'faultBoardAuxUnderVoltage',
    'faultBoardOverVoltage',
    'faultBoardUnderVoltage',
    'faultBoardStackError',
    'faultBoardOpenWireDetect'
];

// Check for any warning
state.hasWarning = warningFlags.some(flag => state[flag] === true);

// Check for any fault
state.hasFault = faultFlags.some(flag => state[flag] === true);

// Build active faults list
let activeFaults = [];
warningFlags.forEach(flag => {
    if (state[flag] === true) activeFaults.push(flag);
});
faultFlags.forEach(flag => {
    if (state[flag] === true) activeFaults.push(flag);
});
state.activeFaults = activeFaults;
state.activeFaultCount = activeFaults.length;

// Store in flow context
flow.set("containerBatteryFaultState", state);

msg.payload = state;
return msg;

var state = flow.get("containerBatteryFaultState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;

const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("containerBatteryState") || {
    kind: "ContainerBatteryState",
    version: 1,
    // Battery Status (0x18FF14F0)
    socPercent: null,
    sohPercent: null,
    cycleCount: null,
    remainingEnergyKwh: null,
    availableEnergyKwh: null,
    // Cell Status (0x18FF11F0)
    totalVoltageV: null,
    currentA: null,
    selectedBmuLoc: null,
    selectedCellLoc: null,
    cellVoltageMv: null,
    cellTempC: null,
    // Max/Min Voltage Status (0x18FF12F0)
    maxCellVoltageCellLoc: null,
    maxCellVoltageBmuLoc: null,
    minCellVoltageCellLoc: null,
    minCellVoltageBmuLoc: null,
    avgCellVoltageMv: null,
    maxCellVoltageMv: null,
    minCellVoltageMv: null,
    // State Message (0x18FF10F0)
    stateCode: null,
    state: null,
    contactStatusPos: null,
    contactFbkPos: null,
    contactFbkNeg: null,
    chargeComplete: null,
    dischargeComplete: null,
    contactStatusNeg: null,
    isolationStatus: null,
    fuseFbk: null,
    input1Status: null,
    ambientTempC: null,
    dmccA: null,
    dmdcA: null,
    // Status2 (0x18FF13F0)
    maxCellTempCellLoc: null,
    maxCellTempBmuLoc: null,
    minCellTempCellLoc: null,
    minCellTempBmuLoc: null,
    maxCellTempC: null,
    minCellTempC: null,
    outVoltPosV: null,
    outVoltNegV: null
};

// Helper functions
function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function getNibbleLow(buf, offset) {
    return buf[offset] & 0x0F;
}

function getNibbleHigh(buf, offset) {
    return (buf[offset] >> 4) & 0x0F;
}

function getBit(buf, byteOffset, bitOffset) {
    return (buf[byteOffset] >> bitOffset) & 0x01;
}

function getBits(buf, byteOffset, bitOffset, length) {
    return (buf[byteOffset] >> bitOffset) & ((1 << length) - 1);
}

// State code to string mapping
const stateMap = {
    0: "N/A",
    101: "Standby",
    102: "Startup",
    103: "Precharge",
    104: "Discharge",
    105: "Charge",
    106: "Shutdown",
    107: "Fault",
    108: "Charge_Complete",
    109: "Discharge_Complete"
};

var processed = false;

// ==================== BCU_01_Battery_Status (0x18FF14F0) ====================
if (canId === 0x18FF14F0) {
    processed = true;
    // Bit 0-7: SOC (8 bit, Factor: 1, Offset: 0)
    state.socPercent = u8(data, 0);
    // Bit 8-15: SOH (8 bit, Factor: 1, Offset: 0)
    state.sohPercent = u8(data, 1);
    // Bit 16-31: Duty Cycle (16 bit, Factor: 1, Offset: 0)
    state.cycleCount = u16(data, 2);
    // Bit 32-47: Remaining Energy (16 bit, Factor: 0.01, Offset: 0)
    state.remainingEnergyKwh = u16(data, 4) * 0.01;
    // Bit 48-63: Available Energy (16 bit, Factor: 0.01, Offset: 0)
    state.availableEnergyKwh = u16(data, 6) * 0.01;
}

// ==================== BCU_01_Cell_Status (0x18FF11F0) ====================
if (canId === 0x18FF11F0) {
    processed = true;
    // Bit 0-15: Total Voltage (16 bit, Factor: 0.1, Offset: 0)
    state.totalVoltageV = u16(data, 0) * 0.1;
    // Bit 16-31: Instant Current (16 bit, Factor: 0.1, Offset: -1000)
    state.currentA = (u16(data, 2) * 0.1) - 1000;
    // Bit 32-35: Selected BMU Location (4 bit)
    state.selectedBmuLoc = getNibbleLow(data, 4);
    // Bit 36-39: Selected Cell Location (4 bit)
    state.selectedCellLoc = getNibbleHigh(data, 4);
    // Bit 40-55: Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.cellVoltageMv = u16(data, 5);
    // Bit 56-63: Cell Temp (8 bit, Factor: 1, Offset: -40)
    state.cellTempC = u8(data, 7) - 40;
}

// ==================== BCU_01_Max_Min_Voltage_Status (0x18FF12F0) ====================
if (canId === 0x18FF12F0) {
    processed = true;
    // Bit 0-3: Max Voltage Cell Location (4 bit)
    state.maxCellVoltageCellLoc = getNibbleLow(data, 0);
    // Bit 4-7: Max Voltage BMU Location (4 bit)
    state.maxCellVoltageBmuLoc = getNibbleHigh(data, 0);
    // Bit 8-11: Min Voltage Cell Location (4 bit)
    state.minCellVoltageCellLoc = getNibbleLow(data, 1);
    // Bit 12-15: Min Voltage BMU Location (4 bit)
    state.minCellVoltageBmuLoc = getNibbleHigh(data, 1);
    // Bit 16-31: Average Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.avgCellVoltageMv = u16(data, 2);
    // Bit 32-47: Max Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.maxCellVoltageMv = u16(data, 4);
    // Bit 48-63: Min Cell Voltage (16 bit, Factor: 1, Offset: 0)
    state.minCellVoltageMv = u16(data, 6);
}

// ==================== BCU_01_State_Message (0x18FF10F0) ====================
if (canId === 0x18FF10F0) {
    processed = true;
    // Bit 0-7: BCU State Code (8 bit)
    state.stateCode = u8(data, 0);
    state.state = stateMap[state.stateCode] || "Unknown";
    // Bit 8: Contact Status POS (1 bit)
    state.contactStatusPos = getBit(data, 1, 0);
    // Bit 9: Contact FBK POS (1 bit)
    state.contactFbkPos = getBit(data, 1, 1);
    // Bit 10: Contact FBK NEG (1 bit)
    state.contactFbkNeg = getBit(data, 1, 2);
    // Bit 11: Charge Complete (1 bit)
    state.chargeComplete = getBit(data, 1, 3) === 1;
    // Bit 12: Discharge Complete (1 bit)
    state.dischargeComplete = getBit(data, 1, 4) === 1;
    // Bit 13: Contact Status NEG (1 bit)
    state.contactStatusNeg = getBit(data, 1, 5);
    // Bit 14-15: Isolation Status (2 bit)
    state.isolationStatus = getBits(data, 1, 6, 2);
    // Bit 16-17: Fuse FBK (2 bit)
    state.fuseFbk = getBits(data, 2, 0, 2);
    // Bit 18-19: Input1 Status (2 bit)
    state.input1Status = getBits(data, 2, 2, 2);
    // Bit 24-31: Ambient Temp (8 bit, Factor: 1, Offset: -40)
    state.ambientTempC = u8(data, 3) - 40;
    // Bit 32-47: DMCC (16 bit, Factor: 0.1, Offset: 0)
    state.dmccA = u16(data, 4) * 0.1;
    // Bit 48-63: DMDC (16 bit, Factor: 0.1, Offset: 0)
    state.dmdcA = u16(data, 6) * 0.1;
}

// ==================== BCU_01_Status2 (0x18FF13F0) ====================
if (canId === 0x18FF13F0) {
    processed = true;
    // Bit 0-3: Max Temp Cell Location (4 bit)
    state.maxCellTempCellLoc = getNibbleLow(data, 0);
    // Bit 4-7: Max Temp BMU Location (4 bit)
    state.maxCellTempBmuLoc = getNibbleHigh(data, 0);
    // Bit 8-11: Min Temp Cell Location (4 bit)
    state.minCellTempCellLoc = getNibbleLow(data, 1);
    // Bit 12-15: Min Temp BMU Location (4 bit)
    state.minCellTempBmuLoc = getNibbleHigh(data, 1);
    // Bit 16-23: Max Cell Temp (8 bit, Factor: 1, Offset: -40)
    state.maxCellTempC = u8(data, 2) - 40;
    // Bit 24-31: Min Cell Temp (8 bit, Factor: 1, Offset: -40)
    state.minCellTempC = u8(data, 3) - 40;
    // Bit 32-47: OutVolt POS (16 bit, Factor: 0.1, Offset: 0)
    state.outVoltPosV = u16(data, 4) * 0.1;
    // Bit 48-63: OutVolt NEG (16 bit, Factor: 0.1, Offset: 0)
    state.outVoltNegV = u16(data, 6) * 0.1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("containerBatteryState", state);
msg.payload = state;
return msg;

