let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

// HVCU_Control_State (0x18FF201Ex)
// CAN ID pattern: 0x18FF2010 - 0x18FF201F
if ((canId & 0xFFFFFFF0) !== 0x18FF2010) {
    return null;
}

// Helper functions
function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function getBit(buf, byteOffset, bitOffset) {
    return ((buf[byteOffset] >> bitOffset) & 0x01) === 1;
}

// State code to string mapping
const stateMap = {
    0: "N/A",
    101: "Standby",
    102: "Startup",
    103: "Precharge",
    104: "Discharge",
    105: "Charge",
    106: "Shutdown"
};

let state = {
    kind: "HVCUControlState",
    version: 1,
    timestampUtc: new Date().toISOString(),

    // Bit 0-7: BCU 01 Control State
    bcu01ControlStateCode: u8(data, 0),
    bcu01ControlState: stateMap[u8(data, 0)] || "Unknown",

    // Bit 8-15: BCU 02 Control State
    bcu02ControlStateCode: u8(data, 1),
    bcu02ControlState: stateMap[u8(data, 1)] || "Unknown",

    // Bit 16-23: BCU 03 Control State
    bcu03ControlStateCode: u8(data, 2),
    bcu03ControlState: stateMap[u8(data, 2)] || "Unknown",

    // Bit 24-31: BCU 04 Control State
    bcu04ControlStateCode: u8(data, 3),
    bcu04ControlState: stateMap[u8(data, 3)] || "Unknown",

    // Bit 32: Pack1 Isolation Control
    pack1IsolationControl: getBit(data, 4, 0)
};

flow.set("hvcuControlState", state);
msg.payload = state;
return msg;

var state = flow.get("hvcuControlState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;

const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("chillerAlarmState") || {
    kind: "ChillerAlarmState",
    version: 1,
    // Chiller_3_Alarm (0x18068040x)
    oICoolantPressSensorFault: null,
    powerSupplyOV: null,
    powerSupplyUV: null,
    systemCoolantShortage: null,
    pumpFaultSummary: null,
    pumpFaultLockSummary: null,
    // Chiller_4_Alarm (0x18078040x)
    oCoolantPressSensorFault: null,
    iCoolantPressureSensorFault: null,
    lowPressureSensorFault: null,
    oCoolantTempSensorFault: null,
    systemLowPressureAlarm: null,
    systemHighPressureAlarm: null,
    dischargeTempTooHighAlarm: null,
    canCommunicationFaultAlarm: null,
    suctionTempSensorFault: null,
    coolingSystemAbnormal: null,
    lowSuctionSuperheatDegreeA: null,
    compressorVfdOvAlarm: null,
    compressorVfdUvAlarm: null,
    compressorVfdOcAlarm: null,
    compressorVfdOtAlarm: null,
    compressorVfdComFaultA: null,
    compressorVfdPhaseLossA: null,
    otherCompVfdFaultAlarm: null,
    pumpLowDiffPressAlarm: null,
    dischargeTempTooHighLock: null,
    systemHighPressLock: null,
    systemLowPressLock: null,
    compressorVfdOcLock: null,
    compressorVfdOvLock: null,
    compressorVfdUvLock: null,
    compressorVfdOtLock: null,
    compressorVfdPhsLossLock: null,
    otherCompVfdFaultLocks: null
};

// Helper function
function getBit(buf, bitIndex) {
    const byteIndex = Math.floor(bitIndex / 8);
    const bitOffset = bitIndex % 8;
    if (byteIndex >= buf.length) return false;
    return ((buf[byteIndex] >> bitOffset) & 0x01) === 1;
}

var processed = false;

// ==================== Chiller_3_Alarm (0x18068040x) ====================
if ((canId & 0xFFFFFFF0) === 0x18068040) {
    processed = true;
    state.oICoolantPressSensorFault = getBit(data, 0);
    state.powerSupplyOV = getBit(data, 1);
    state.powerSupplyUV = getBit(data, 2);
    state.systemCoolantShortage = getBit(data, 3);
    state.pumpFaultSummary = getBit(data, 4);
    state.pumpFaultLockSummary = getBit(data, 5);
}

// ==================== Chiller_4_Alarm (0x18078040x) ====================
if ((canId & 0xFFFFFFF0) === 0x18078040) {
    processed = true;
    state.oCoolantPressSensorFault = getBit(data, 0);
    state.iCoolantPressureSensorFault = getBit(data, 1);
    state.lowPressureSensorFault = getBit(data, 2);
    state.oCoolantTempSensorFault = getBit(data, 3);
    state.systemLowPressureAlarm = getBit(data, 4);
    state.systemHighPressureAlarm = getBit(data, 5);
    state.dischargeTempTooHighAlarm = getBit(data, 6);
    state.canCommunicationFaultAlarm = getBit(data, 7);
    state.suctionTempSensorFault = getBit(data, 8);
    state.coolingSystemAbnormal = getBit(data, 9);
    state.lowSuctionSuperheatDegreeA = getBit(data, 10);
    state.compressorVfdOvAlarm = getBit(data, 11);
    state.compressorVfdUvAlarm = getBit(data, 12);
    state.compressorVfdOcAlarm = getBit(data, 13);
    state.compressorVfdOtAlarm = getBit(data, 14);
    state.compressorVfdComFaultA = getBit(data, 15);
    state.compressorVfdPhaseLossA = getBit(data, 16);
    state.otherCompVfdFaultAlarm = getBit(data, 17);
    state.pumpLowDiffPressAlarm = getBit(data, 18);
    state.dischargeTempTooHighLock = getBit(data, 19);
    state.systemHighPressLock = getBit(data, 20);
